 * A small, correct memoized-selector library (reselect-style).
 *
 * - defaultMemoize(fn, equalityCheck): memoizes a single-argument-ish
 *   function on its argument list, cache size 1, keyed by reference
 *   equality of the arguments by default.
 * - createSelector(inputSelectors, combiner): returns a selector that,
 *   when called with (...args), computes input values via the input
 *   selectors and only runs `combiner` if any input value changed
 *   (per equalityCheck). Exposes recomputations() for testing.
 * - createStructuredSelector({key: selector}): maps a state object to
 *   an object of selector results; output is reference-stable while
 *   every sub-selector's result is unchanged.
 */

export function defaultEqualityCheck(a, b) {
  return a === b;
}

function areArgumentsShallowlyEqual(equalityCheck, prev, next) {
  if (prev === null || next === null || prev.length !== next.length) {
    return false;
  }
  for (let i = 0; i < prev.length; i++) {
    if (!equalityCheck(prev[i], next[i])) {
      return false;
    }
  }
  return true;
}

/**
 * Memoize `fn` with a cache size of 1, keyed on its arguments.
 *
 * @param {Function} fn - function to memoize
 * @param {(a: any, b: any) => boolean} [equalityCheck] -
 *        per-argument comparison; defaults to reference equality (===).
 */
export function defaultMemoize(fn, equalityCheck = defaultEqualityCheck) {
  let lastArgs = null;
  let lastResult = null;
  let hasRun = false;

  const memoized = function (...args) {
    if (!hasRun || !areArgumentsShallowlyEqual(equalityCheck, lastArgs, args)) {
      lastResult = fn.apply(this, args);
      hasRun = true;
    }
    lastArgs = args;
    return lastResult;
  };

  memoized.clearCache = () => {
    hasRun = false;
    lastArgs = null;
    lastResult = null;
  };

  return memoized;
}

/**
 * Create a memoized selector from input selectors and a combiner.
 *
 * @param {Array<(state: any, ...rest: any[]) => any>} inputSelectors
 * @param {Function} combiner - (...inputValues) => result
 * @returns {(state: any, ...rest: any[]) => any} selector with:
 *          - resultFunc: the raw combiner
 *          - dependencies: the input selectors
 *          - recomputations(): number of times the combiner ran
 *          - clearCache()
 */
export function createSelector(inputSelectors, combiner) {
  if (!Array.isArray(inputSelectors)) {
    throw new TypeError(
      'createSelector expects an array of input selectors as its first argument'
    );
  }

  let recomputationCount = 0;

  const memoizedCombiner = defaultMemoize(function (...inputValues) {
    recomputationCount += 1;
    return combiner(...inputValues);
  });

  const selector = defaultMemoize(function (state, ...rest) {
    const inputValues = inputSelectors.map((input) =>
      typeof input === 'function' ? input(state, ...rest) : input
    );
    return memoizedCombiner(...inputValues);
  });

  // Re-expose the inner memoization so tests can inspect recompute counts.
  selector.resultFunc = combiner;
  selector.recomputations = () => recomputationCount;
  selector.resetRecomputations = () => {
    recomputationCount = 0;
    return recomputationCount;
  };
  selector.dependencies = inputSelectors;
  selector.clearCache = () => {
    memoizedCombiner.clearCache();
    selector.clearCache();
  };

  return selector;
}

/**
 * Create a selector that returns `{key1: ..., key2: ...}` computed from
 * per-key selectors. The returned object keeps reference identity while
 * all key results are unchanged.
 *
 * @param {Record<string, (state: any, ...rest: any[]) => any>} selectors
 */
export function createStructuredSelector(selectors) {
  const keys = Object.keys(selectors);

  const structuredSelector = (state, ...rest) => {
    let changed = false;
    const result = {};
    for (const key of keys) {
      const value =
        typeof selectors[key] === 'function'
          ? selectors[key](state, ...rest)
          : selectors[key];
      if (!Object.prototype.hasOwnProperty.call(structuredSelector._last, key) || structuredSelector._last[key] !== value) {
        changed = true;
      }
      result[key] = value;
    }
    if (!changed && structuredSelector._hasLast) {
      return structuredSelector._lastResult;
    }
    structuredSelector._last = result;
    structuredSelector._hasLast = true;
    structuredSelector._lastResult = result;
    return result;
  };

  structuredSelector._last = {};
  structuredSelector._hasLast = false;
  structuredSelector._lastResult = undefined;

  return structuredSelector;
}
