result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/selectors/test/selectors.test.mjs", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  createSelector,
  createStructuredSelector,
  defaultMemoize,
} from '../src/index.mjs';

const stateA = (s) => s.a;
const stateB = (s) => s.b;

test('combiner does not run when inputs are reference-equal even if top-level state changed', () => {
  let calls = 0;
  const selector = createSelector([stateA], (a) => {
    calls += 1;
    return a;
  });

  const s1 = { a: { x: 1 }, b: 'noise' };
  const s2 = { a: s1.a, b: 'different' }; // new top-level object, same `a` branch
  const s3 = { a: s1.a, b: { deep: [1, 2, 3] } };

  const r1 = selector(s1);
  const r2 = selector(s2);
  const r3 = selector(s3);

  assert.equal(calls, 1);
  assert.equal(selector.recomputations(), 1);
  assert.equal(r1, r2);
  assert.equal(r2, r3);
});

test('combiner runs when the relevant branch changes', () => {
  const selector = createSelector([stateA, stateB], (a, b) => ({ a, b }));

  const s1 = { a: 1, b: 'x' };
  const s2 = { a: 2, b: 'x' };
  const s3 = { a: 2, b: 'y' };

  selector(s1);
  assert.equal(selector.recomputations(), 1);
  selector(s2);
  assert.equal(selector.recomputations(), 2);
  selector(s3);
  assert.equal(selector.recomputations(), 3);
});

test('irrelevant branch updates never trigger recompute', () => {
  const relevantSelector = createSelector([stateA], (a) => a * 10);

  const s1 = { a: 3, irrelevant: { big: 'object' } };
  const s2 = { a: 3, irrelevant: { big: 'object', extra: true } };
  const s3 = { a: 3, irrelevant: null };

  assert.equal(relevantSelector(s1), 30);
  assert.equal(relevantSelector(s1), 30);
  assert.equal(relevantSelector(s2), 30);
  assert.equal(relevantSelector(s3), 30);
  assert.equal(relevantSelector.recomputations(), 1);
});

test('custom shallow-equality equalityCheck lets rebuilt-but-equal input skip recompute', () => {
  const shallowEqual = (a, b) => {
    if (a === b) return true;
    if (
      typeof a !== 'object' ||
      typeof b !== 'object' ||
      a === null ||
      b === null
    ) {
      return false;
    }
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    return ka.every((k) => a[k] === b[k]);
  };

  // input selector returns a freshly-built object each call
  const rebuiltInput = (state) => ({
    x: state.a.x,
    y: state.a.y,
  });

  let combinerCalls = 0;
  const selector = createSelector(
    [rebuiltInput],
    (input) => {
      combinerCalls += 1;
      return input.x + input.y;
    },
  );

  // wrap with defaultMemoize's equality check by using it via createSelector:
  // instead, build a second selector that applies shallow equality at the
  // memoization layer.
  const memoizedCombiner = defaultMemoize(
    (input) => {
      combinerCalls += 1;
      return input.x + input.y;
    },
    shallowEqual,
  );
  const shallowSelector = (state) => memoizedCombiner(rebuiltInput(state));

  // reference-equality version: rebuilt object forces recompute every time
  selector({ a: { x: 1, y: 2 } });
  selector({ a: { x: 1, y: 2 } }); // equal content, different identity
  assert.equal(selector.recomputations(), 2);

  // shallow-equality version: rebuilt-but-equal skips the recompute
  const s1 = { a: { x: 1, y: 2 } };
  const s2 = { a: { x: 1, y: 2 } }; // rebuilt branch, equal contents
  assert.equal(shallowSelector(s1), 3);
  assert.equal(shallowSelector(s2), 3);
  assert.equal(combinerCalls, 3); // only the first shallow call computed

  // actual change still recomputes
  assert.equal(shallowSelector({ a: { x: 10, y: 2 } }), 12);
  assert.equal(combinerCalls, 4);
});

test('createStructuredSelector keeps output identity when nothing changed', () => {
  const selector = createStructuredSelector({
    total: createSelector([stateA], (a) => a + 1),
    label: createSelector([stateB], (b) => b.toUpperCase()),
  });

  const s1 = { a: 1, b: 'hi' };
  const out1 = selector(s1);
  assert.deepEqual(out1, { total: 2, label: 'HI' });

  // new top-level state, same branches -> same output object identity
  const out2 = selector({ a: 1, b: 'hi' });
  assert.equal(out1, out2);

  // changing one key produces a new object with updated value
  const out3 = selector({ a: 5, b: 'hi' });
  assert.notEqual(out1, out3);
  assert.deepEqual(out3, { total: 6, label: 'HI' });

  // and back to unchanged state relative to out3
  const out4 = selector({ a: 5, b: 'hi' });
  assert.equal(out3, out4);
});

test('chained selectors only recompute affected stages', () => {
  const counts = { stage1: 0, stage2: 0, stage3: 0 };

  const selectItems = createSelector([(s) => s.items], (items) => {
    counts.stage1 += 1;
    return items.filter((i) => i.active);
  });

  const selectActiveCount = createSelector([selectItems], (active) => {
    counts.stage2 += 1;
    return active.length;
  });

  const selectSummary = createSelector(
    [selectActiveCount, (s) => s.title],
    (count, title) => {
      counts.stage3 += 1;
      return `${title}: ${count}`;
    },
  );

  const s1 = {
    items: [
      { id: 1, active: true },
      { id: 2, active: false },
    ],
    title: 'list',
  };

  assert.equal(selectSummary(s1), 'list: 1');
  assert.deepEqual(counts, { stage1: 1, stage2: 1, stage3: 1 });

  // irrelevant change (title untouched? no — items untouched): only stage3 runs
  const s2 = { ...s1, title: 'renamed' };
  assert.equal(selectSummary(s2), 'renamed: 1');
  assert.deepEqual(counts, { stage1: 1, stage2: 1, stage3: 2 });

  // unrelated top-level churn: nothing recomputes
  const s3 = { ...s2, junk: Symbol('x') };
  selectSummary(s3);
  assert.deepEqual(counts, { stage1: 1, stage2: 1, stage3: 2 });

  // items change: stages 1-3 all rerun
  const s4 = {
    items: [
      { id: 1, active: true },
      { id: 2, active: true },
    ],
    title: 'renamed',
  };
  assert.equal(selectSummary(s4), 'renamed: 2');
  assert.deepEqual(counts, { stage1: 2, stage2: 2, stage3: 3 });

  // items array rebuilt but same filtered result identity is not preserved
  // here (filter makes a new array), so stage1+2 rerun; that is expected for
  // reference-based memoization.
  const s5 = { ...s4, extra: 1 };
  selectSummary(s5);
  assert.deepEqual(counts, { stage1: 3, stage2: 3, stage3: 4 });
});

test('defaultMemoize basics', () => {
  let calls = 0;
  const fn = defaultMemoize((x, y) => {
    calls += 1;
    return x + y;
  });
  assert.equal(fn(1, 2), 3);
  assert.equal(fn(1, 2), 3);
  assert.equal(calls, 1);
  assert.equal(fn(1, 3), 4);
  assert.equal(calls, 2);
  fn.clearCache();
  assert.equal(fn(1, 3), 4);
  assert.equal(calls, 3);
});
"})
